#!/usr/bin/env node

/**
 * P1-1: Enrich Descriptions Script
 *
 * 목적: 133개 프로젝트 각각에 1-2줄 설명 추가
 * 전략:
 *   1. 기존 설명이 있으면 그대로 사용
 *   2. 없으면 프로젝트명 분석해서 자동 생성
 *   3. 알려진 프로젝트는 수동 오버라이드
 *
 * 사용법: node enrich-descriptions.js /path/to/projects.json
 */

const fs = require('fs');
const path = require('path');

// 알려진 프로젝트 설명 (수동 정의)
const KNOWN_DESCRIPTIONS = {
  'freelang-v4-compiler': 'FreeLang v4 main compiler with optimization passes and LLVM backend integration.',
  'freelang-v6-ai-sovereign': 'AI-driven FreeLang compiler variant for autonomous optimization based on runtime feedback.',
  'freelang-to-c': 'FreeLang to C transpiler enabling self-hosting proof (minicc.fl bootstrapping).',
  'freelang-os-kernel': 'FreeLang-based operating system kernel with multiboot, memory management, and syscalls.',
  'freelang-blockchain-dpos': 'Delegated proof-of-stake blockchain implementation in FreeLang.',
  'sovereign-workspace': 'Genspark-alternative local AI workspace with FV-Lang functional programming.',
  'personal-code-os': 'Browser-based self-hosted OS with OPFS/IDB storage and FV-Lang REPL.',
  'freewire': 'Node-based visual programming to FreeLang compiler with AI node generator.',
  'fv-lang': 'Pure functional programming language with Haskell-like syntax and Rust-like type system.',
  'kim-project-cli': 'Integrated project management CLI (288 GOGS + 27 local projects) with memo API.',
  'c-compiler-from-scratch': '19K-line C compiler with lexer/parser/codegen/ELF generation and SAI optimizer.',
  'challenge-17-quantum-crypto': 'CTF challenge: quantum-resistant cryptography implementation.',
};

// 프로젝트 카테고리별 기본 설명 템플릿
const CATEGORY_TEMPLATES = {
  'core': (name) => generateCoreDescription(name),
  'modules': (name) => generateModuleDescription(name),
  'archived': (name) => generateArchivedDescription(name),
  'experiments': (name) => generateExperimentDescription(name),
};

function generateCoreDescription(name) {
  const lowerName = name.toLowerCase();

  // Version-based
  if (lowerName.includes('v4-')) {
    return `FreeLang v4 ${extractFeature(name)} module for production use.`;
  }
  if (lowerName.includes('v6-')) {
    return `FreeLang v6 advanced ${extractFeature(name)} with AI-driven optimization.`;
  }
  if (lowerName.includes('v2-')) {
    return `FreeLang v2 legacy ${extractFeature(name)} (archived version line).`;
  }

  // Phase-based
  if (lowerName.includes('phase')) {
    const phaseNum = lowerName.match(/phase(\d+)/)?.[1] || 'N';
    return `FreeLang Phase ${phaseNum} development milestone with incremental improvements.`;
  }

  // Feature-based
  if (lowerName.includes('backend')) return 'Backend infrastructure for FreeLang runtime and services.';
  if (lowerName.includes('frontend')) return 'Web UI and frontend components for FreeLang tooling.';
  if (lowerName.includes('compiler')) return 'Compiler infrastructure with optimization and code generation.';
  if (lowerName.includes('runtime')) return 'Runtime environment and virtual machine for FreeLang execution.';
  if (lowerName.includes('stdlib')) return 'Standard library providing core data structures and algorithms.';
  if (lowerName.includes('kernel')) return 'OS kernel implementation providing system-level abstractions.';
  if (lowerName.includes('database') || lowerName.includes('sqlite')) return 'Database integration layer with connection pooling and query optimization.';

  return `${extractFeature(name)} component of FreeLang ecosystem.`;
}

function generateModuleDescription(name) {
  const lowerName = name.toLowerCase();

  if (lowerName.includes('jit')) return 'Just-in-time compiler for dynamic FreeLang code optimization.';
  if (lowerName.includes('compiler')) return 'Compiler module for code transformation and optimization.';
  if (lowerName.includes('runtime')) return 'Runtime module providing execution environment.';
  if (lowerName.includes('orm')) return 'Object-relational mapping library for database operations.';
  if (lowerName.includes('llvm')) return 'LLVM integration for machine code generation.';
  if (lowerName.includes('zig') || lowerName.includes('rust')) return `${extractFeature(name)} language compiler or learning project.`;

  return `Reusable module for ${extractFeature(name)} functionality.`;
}

function generateArchivedDescription(name) {
  const lowerName = name.toLowerCase();
  return `[ARCHIVED] Previous version of ${extractFeature(name)} - see current version for maintained code.`;
}

function generateExperimentDescription(name) {
  const lowerName = name.toLowerCase();

  if (lowerName.match(/\d\.\d/)) {
    const version = lowerName.match(/(\d\.\d)/)[1];
    return `Experimental research iteration ${version} exploring ${extractFeature(name)} concepts.`;
  }

  return `Experimental prototype for ${extractFeature(name)} - early stage research.`;
}

function extractFeature(name) {
  // 프로젝트명에서 의미있는 키워드 추출
  const parts = name
    .toLowerCase()
    .replace(/^(freelang|fv|grie|mindlang|test|zig|rust|challenge)-/, '')
    .replace(/-(phase|v\d|series).*$/, '')
    .replace(/-/g, ' ')
    .trim();

  return parts || 'core functionality';
}

// 메인 로직
function enrichDescriptions(projectsJsonPath) {
  if (!fs.existsSync(projectsJsonPath)) {
    console.error(`❌ File not found: ${projectsJsonPath}`);
    process.exit(1);
  }

  const data = JSON.parse(fs.readFileSync(projectsJsonPath, 'utf-8'));
  const projects = Array.isArray(data) ? data : data.projects || [];

  let enriched = 0;
  let skipped = 0;

  const enhanced = projects.map(project => {
    // 1. 기존 설명이 있으면 유지
    if (project.description && project.description.length > 5) {
      skipped++;
      return project;
    }

    // 2. 알려진 프로젝트 확인
    const projectName = project.name || project.path?.split('/').pop() || '';
    if (KNOWN_DESCRIPTIONS[projectName]) {
      project.description = KNOWN_DESCRIPTIONS[projectName];
      enriched++;
      console.log(`✅ [KNOWN] ${projectName}`);
      return project;
    }

    // 3. 카테고리별 자동 생성
    const category = project.category || 'core';
    const template = CATEGORY_TEMPLATES[category] || CATEGORY_TEMPLATES['core'];
    project.description = template(projectName);
    enriched++;
    console.log(`🔄 [AUTO-${category.toUpperCase()}] ${projectName}`);

    return project;
  });

  // 파일 저장
  const outputPath = projectsJsonPath.replace('.json', '-enhanced.json');
  const output = Array.isArray(data) ? enhanced : { ...data, projects: enhanced };
  fs.writeFileSync(outputPath, JSON.stringify(output, null, 2));

  // 통계 출력
  console.log('\n' + '='.repeat(60));
  console.log(`📊 Enrichment Summary:`);
  console.log(`   ✅ Enriched: ${enriched} projects`);
  console.log(`   ⏭️  Skipped: ${skipped} projects (already have descriptions)`);
  console.log(`   📁 Output: ${outputPath}`);
  console.log('='.repeat(60) + '\n');

  return {
    total: projects.length,
    enriched,
    skipped,
    outputPath,
  };
}

// CLI Entry Point
const projectsJsonPath = process.argv[2];
if (!projectsJsonPath) {
  console.error('사용법: node enrich-descriptions.js <projects.json 경로>');
  console.error('예제: node enrich-descriptions.js ~/kim-project-cli/projects.json');
  process.exit(1);
}

try {
  const result = enrichDescriptions(projectsJsonPath);
  console.log(`\n✨ 완료! ${result.enriched}/${result.total} 프로젝트에 설명 추가됨`);
} catch (error) {
  console.error('❌ 오류:', error.message);
  process.exit(1);
}

