  });

  // 3. 버전 진화 관계 추가
  const versionDeps = inferVersionEvolution(projects);
  let versionCount = 0;
  Object.entries(versionDeps).forEach(([project, deps]) => {
    if (deps.length > 0 && dependencies[project]) {
      dependencies[project] = [...new Set([...dependencies[project], ...deps])];
