      console.log(`📦 [VERSION] ${project} → ${deps.join(', ')}`);
    }
  });

  // 4. 카테고리 기반 의존성
  const categoryDeps = inferCategoryDependencies(projects);
  let categoryCount = 0;
  Object.entries(categoryDeps).forEach(([project, deps]) => {
    if (deps.length > 0 && dependencies[project]) {
      dependencies[project] = [...new Set([...dependencies[project], ...deps])];
      categoryCount++;
      if (categoryCount <= 10) {
        console.log(`📁 [CATEGORY] ${project} → ${deps.join(', ')}`);
      }
    }
  });

  if (categoryCount > 10) {
    console.log(`   ... and ${categoryCount - 10} more category-based relationships`);
  }

  // 역 의존성 맵 생성 (used_by)
  const reverseDeps = {};
  projects.forEach(p => {
    reverseDeps[p.name || ''] = [];
  });

  Object.entries(dependencies).forEach(([project, deps]) => {
    deps.forEach(dep => {
      if (reverseDeps[dep]) {
        reverseDeps[dep].push(project);
      }
    });
  });

  // 파일 저장
  const dirPath = path.dirname(projectsJsonPath);
