        dependencies,
      },
      null,
      2
    )
  );

  fs.writeFileSync(
    reversePath,
    JSON.stringify(
      {
        generatedAt: new Date().toISOString(),
        description: 'Reverse dependencies: which projects use this project',
        usedBy: reverseDeps,
      },
      null,
      2
    )
  );

  // 통계
  const projectsWithDeps = Object.entries(dependencies).filter(([, deps]) => deps.length > 0);
  const totalDeps = Object.values(dependencies).flat().length;
  const avgDeps = projectsWithDeps.length > 0 ? (totalDeps / projectsWithDeps.length).toFixed(1) : 0;

