  console.log(`   🔗 Average dependencies per project: ${avgDeps}`);
  console.log(`   📄 Output files:`);
  console.log(`      - ${depsPath}`);
  console.log(`      - ${reversePath}`);
  console.log('='.repeat(60) + '\n');
}

// CLI Entry Point
const projectsJsonPath = process.argv[2];
if (!projectsJsonPath) {
  console.error('사용법: node extract-dependencies.js <projects.json 경로>');
  console.error('예제: node extract-dependencies.js ~/kim-project-cli/projects.json');
