#!/usr/bin/env node

/**
 * P1-2: Extract Dependencies Script
 *
 * 목적: 프로젝트 간 의존성 관계를 분석하여 그래프 생성
 *
 * 분석 방식:
 *   1. 프로젝트명 패턴 분석 (v4/v6 라인, phase 진화)
 *   2. 카테고리 관계 파악 (core → modules 의존)
 *   3. 알려진 의존성 매핑 (수동 정의)
 *
 * 출력:
 *   - dependencies.json: {projectName → [depends_on]} 그래프
 *   - reverse-deps.json: {projectName → [used_by]} 역 그래프
 *
 * 사용법: node extract-dependencies.js /path/to/projects.json
 */

const fs = require('fs');
const path = require('path');

// 알려진 의존성 명시적 정의
const KNOWN_DEPENDENCIES = {
  // v4 라인
  'freelang-v4-compiler': ['freelang-v4-optimizer', 'freelang-module-system'],
  'freelang-v4-optimizer': ['freelang-v4-compiler'],
  'freelang-v4-orm': ['freelang-v4-compiler', 'freelang-raft-db'],
  'freelang-v4-crypto': ['freelang-v4-compiler'],

  // v6 라인 (v4를 확장)
  'freelang-v6-ai-sovereign': ['freelang-v4-compiler', 'freelang-quantum-internet'],
  'freelang-v6-source': ['freelang-v4-compiler', 'freelang-v6-ai-sovereign'],

  // Core 시스템
  'freelang-os-kernel': ['freelang-runtime', 'freelang-module-system'],
  'freelang-runtime': ['freelang-v4-compiler', 'freelang-memory-management'],
  'freelang-module-system': ['freelang-v4-compiler'],

  // Transpiler
  'freelang-to-c': ['freelang-v4-compiler', 'freelang-v4-optimizer'],
  'freelang-to-zlang': ['freelang-v4-compiler'],

  // Functional Language
  'fv-lang': ['freelang-v4-compiler'],
  'personal-code-os': ['fv-lang'],
  'sovereign-workspace': ['fv-lang'],

  // Visual Programming
  'freewire': ['freelang-v4-compiler', 'fv-lang'],

  // Database
  'freelang-raft-db': ['freelang-v4-compiler'],
  'freelang-sqlite-integration': ['freelang-v4-compiler'],

  // Blockchain
  'freelang-blockchain-dpos': ['freelang-v4-compiler', 'freelang-raft-db'],

  // Backend Systems
  'freelang-backend-system': ['freelang-v4-compiler', 'freelang-raft-db'],
  'freelang-backend-production': ['freelang-backend-system', 'freelang-monitoring-suite'],

  // Monitoring
  'freelang-monitoring-suite': ['freelang-v4-compiler'],
  'freelang-signal': ['freelang-monitoring-suite'],
  'freelang-pulse-ai': ['freelang-monitoring-suite'],

  // Network
  'freelang-sovereign-network': ['freelang-v4-compiler', 'freelang-http-engine'],
  'freelang-http-engine': ['freelang-v4-compiler'],
  'freelang-rest-api': ['freelang-http-engine'],

  // CLI Tool
  'kim-project-cli': ['freelang-v4-compiler'],

  // Phase-based Evolution
  'freelang-comprehensive-course': ['freelang-v4-compiler', 'freelang-v6-source'],
};

// 카테고리 규칙
const CATEGORY_RULES = {
  'modules': 'depends_on_core',  // 모듈은 core에 의존
  'core': 'may_depend_on_modules', // core는 모듈을 사용할 수 있음
  'archived': 'no_analysis', // 아카이브는 분석 제외
  'experiments': 'optional_dependencies', // 실험은 선택적
};

// Phase 진화 관계
function inferPhaseEvolution(projects) {
  const phaseMap = {};

  projects.forEach(p => {
    const name = p.name || '';
    const phaseMatch = name.match(/phase(\d+)/i);
    if (phaseMatch) {
      const phaseNum = parseInt(phaseMatch[1]);
      if (!phaseMap[phaseNum]) phaseMap[phaseNum] = [];
      phaseMap[phaseNum].push(name);
    }
  });

  const phaseDeps = {};
  Object.keys(phaseMap)
    .map(Number)
    .sort((a, b) => a - b)
    .forEach((phase, idx, sorted) => {
      if (idx > 0) {
        const prevPhase = sorted[idx - 1];
        phaseMap[phase].forEach(current => {
          phaseDeps[current] = phaseDeps[current] || [];
          // 이전 phase의 같은 기능 프로젝트에 의존
          phaseMap[prevPhase].forEach(prev => {
            const currentBase = current.replace(new RegExp(`phase${phase}`, 'i'), 'PHASE');
            const prevBase = prev.replace(new RegExp(`phase${prevPhase}`, 'i'), 'PHASE');
            if (currentBase === prevBase && current !== prev) {
              phaseDeps[current].push(prev);
            }
          });
        });
      }
    });

  return phaseDeps;
}

// 버전 진화 관계 (v2 → v4 → v6)
function inferVersionEvolution(projects) {
  const versionDeps = {};

  // v4는 v2를 개선한 버전
  const v4Projects = projects.filter(p => (p.name || '').includes('v4-'));
  const v2Projects = projects.filter(p => (p.name || '').includes('v2-'));

  v4Projects.forEach(p4 => {
    const baseName = (p4.name || '').replace('v4-', '');
    const v2Match = v2Projects.find(p2 => (p2.name || '').includes(`v2-${baseName}`));
    if (v2Match) {
      versionDeps[p4.name] = versionDeps[p4.name] || [];
      versionDeps[p4.name].push(v2Match.name);
    }
  });

  // v6는 v4를 확장
  const v6Projects = projects.filter(p => (p.name || '').includes('v6-'));
  v6Projects.forEach(p6 => {
    versionDeps[p6.name] = versionDeps[p6.name] || [];
    // v6는 일반적으로 v4-compiler에 의존
    versionDeps[p6.name].push('freelang-v4-compiler');
  });

  return versionDeps;
}

// Category-based inference
function inferCategoryDependencies(projects) {
  const categoryDeps = {};

  const coreProjects = projects
    .filter(p => (p.category || 'core') === 'core')
    .map(p => p.name);
  const moduleProjects = projects
    .filter(p => p.category === 'modules')
    .map(p => p.name);

  // 모듈은 core 프로젝트에 의존할 수 있음
  moduleProjects.forEach(module => {
    const baseName = module.replace(/-/g, ' ');

    // 유사한 core 프로젝트 찾기
    const relevantCore = coreProjects.find(core =>
      baseName.includes(core.replace('freelang-', '').split('-')[0])
    );

    if (relevantCore) {
      categoryDeps[module] = categoryDeps[module] || [];
      if (!categoryDeps[module].includes(relevantCore)) {
        categoryDeps[module].push(relevantCore);
      }
    }
  });

  return categoryDeps;
}

// 메인 함수
function extractDependencies(projectsJsonPath) {
  if (!fs.existsSync(projectsJsonPath)) {
    console.error(`❌ File not found: ${projectsJsonPath}`);
