  // 2. Phase 진화 관계 추가
  const phaseDeps = inferPhaseEvolution(projects);
  let phaseCount = 0;
  Object.entries(phaseDeps).forEach(([project, deps]) => {
    if (deps.length > 0 && dependencies[project]) {
      dependencies[project] = [...new Set([...dependencies[project], ...deps])];
      phaseCount++;
      console.log(`🔄 [PHASE] ${project} → ${deps.join(', ')}`);
    }
  });

