#!/usr/bin/env node

/**
 * P1-3: Sync Updated-At Script
 *
 * 목적: GOGS API를 통해 각 프로젝트의 마지막 커밋 정보 수집
 *
 * 수집 정보:
 *   - updated_at: 마지막 커밋 시간
 *   - commit_count: 총 커밋 수
 *   - commit_count_90d: 지난 90일 커밋 수
 *   - last_commit_author: 마지막 커밋 작성자
 *
 * GOGS API 사용:
 *   GET /api/v1/repos/{owner}/{repo} → repository info
 *   GET /api/v1/repos/{owner}/{repo}/commits → commit history
 *
 * 사용법: node sync-updated-at.js <projects.json> [--gogs-api URL] [--token TOKEN]
 */

const fs = require('fs');
const path = require('path');
const https = require('https');

// GOGS 설정 (환경변수 또는 .env 파일에서 읽기)
const GOGS_API = process.env.GOGS_API || 'https://gogs.dclub.kr/api/v1';
const GOGS_TOKEN = process.env.GOGS_TOKEN || '';
const GOGS_HOST = process.env.GOGS_HOST || 'gogs.dclub.kr';

// HTTP GET 요청 (HTTPS 기본)
function fetchUrl(url, token) {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: GOGS_HOST,
      path: url,
      method: 'GET',
      headers: {
        'Authorization': `token ${token}`,
        'User-Agent': 'FreeLang-Project-Excellence/1.0',
      },
    };

    const request = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        try {
          if (res.statusCode === 200) {
            resolve(JSON.parse(data));
          } else if (res.statusCode === 404) {
            resolve(null); // Repository not found
          } else {
            reject(new Error(`HTTP ${res.statusCode}: ${data}`));
          }
        } catch (e) {
          reject(e);
        }
      });
    });

    request.on('error', reject);
    request.end();
  });
}

// GOGS에서 리포지토리 정보 가져오기
async function fetchRepoInfo(owner, repoName, token) {
  try {
    const url = `/api/v1/repos/${owner}/${repoName}`;
    const data = await fetchUrl(url, token);
    return data;
  } catch (error) {
    console.warn(`⚠️  Failed to fetch repo ${owner}/${repoName}: ${error.message}`);
    return null;
  }
}

// GOGS에서 커밋 히스토리 가져오기
async function fetchCommitHistory(owner, repoName, token) {
  try {
    const url = `/api/v1/repos/${owner}/${repoName}/commits?per_page=100`;
    const data = await fetchUrl(url, token);
    return Array.isArray(data) ? data : [];
  } catch (error) {
    console.warn(`⚠️  Failed to fetch commits for ${owner}/${repoName}: ${error.message}`);
    return [];
  }
}

// 프로젝트 경로에서 owner와 repo 추출
function parseRepoPath(gogsPath) {
  // 형식: /kim/freelang-v4-compiler 또는 kim/freelang-v4-compiler
  const parts = gogsPath.replace(/^\//, '').split('/');
  if (parts.length >= 2) {
    return { owner: parts[0], repo: parts[1] };
  }
  return null;
}

// 90일 이내 커밋 수 계산
function getCommitsIn90Days(commits) {
  const now = new Date();
  const ninetyDaysAgo = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);

  return commits.filter(commit => {
    const commitDate = new Date(commit.commit?.committer?.date || commit.created_at);
    return commitDate >= ninetyDaysAgo;
  }).length;
}

// 메인 함수
async function syncUpdatedAt(projectsJsonPath, token = GOGS_TOKEN) {
  if (!fs.existsSync(projectsJsonPath)) {
    console.error(`❌ File not found: ${projectsJsonPath}`);
    process.exit(1);
  }

  if (!token) {
    console.warn('⚠️  No GOGS_TOKEN provided. Using read-only access (rate-limited).');
  }

  const data = JSON.parse(fs.readFileSync(projectsJsonPath, 'utf-8'));
  const projects = Array.isArray(data) ? data : data.projects || [];

  console.log(`🔄 Syncing metadata for ${projects.length} projects...\n`);

  let updated = 0;
  let notFound = 0;
  let errors = 0;

  // 병렬 처리를 위한 배치 함수 (동시 요청 제한)
  const batchSize = 5;
  for (let i = 0; i < projects.length; i += batchSize) {
    const batch = projects.slice(i, i + batchSize);

    await Promise.all(
      batch.map(async (project) => {
        const gogsPath = project.path || project.repo;
        if (!gogsPath) {
          console.warn(`⚠️  [SKIP] No path/repo for ${project.name}`);
          return;
        }

        const parsed = parseRepoPath(gogsPath);
        if (!parsed) {
          console.warn(`⚠️  [INVALID] Cannot parse path: ${gogsPath}`);
          return;
        }

        try {
          // 병렬로 리포지토리 정보와 커밋 히스토리 가져오기
          const [repoInfo, commits] = await Promise.all([
            fetchRepoInfo(parsed.owner, parsed.repo, token),
            fetchCommitHistory(parsed.owner, parsed.repo, token),
          ]);

          if (!repoInfo) {
            notFound++;
            console.log(`❌ [NOT FOUND] ${gogsPath}`);
            return;
          }

          // 메타데이터 업데이트
          project.updated_at = repoInfo.updated_at || repoInfo.pushed_at || new Date().toISOString();
          project.commit_count = repoInfo.commit_count || commits.length;
          project.commit_count_90d = getCommitsIn90Days(commits);
          project.last_commit_author =
            commits[0]?.commit?.author?.name || repoInfo.owner?.full_name || 'Unknown';
          project.repo_url = repoInfo.html_url || '';

          updated++;

          // 진행 상태 출력 (90일 커밋이 있는 프로젝트만)
          if (project.commit_count_90d > 0) {
            console.log(
              `✅ [ACTIVE] ${parsed.owner}/${parsed.repo} → ${project.commit_count} commits, ${project.commit_count_90d} in 90d`
            );
          } else {
            console.log(`⏸️  [INACTIVE] ${parsed.owner}/${parsed.repo} → last: ${project.updated_at}`);
          }
        } catch (error) {
          errors++;
          console.error(`❌ [ERROR] ${gogsPath}: ${error.message}`);
        }
      })
    );

    // 배치 간 대기 (rate limiting)
    if (i + batchSize < projects.length) {
      await new Promise(resolve => setTimeout(resolve, 500));
    }
  }

  // 파일 저장
  const outputPath = projectsJsonPath.replace('.json', '-with-metadata.json');
  const output = Array.isArray(data) ? projects : { ...data, projects };
  fs.writeFileSync(outputPath, JSON.stringify(output, null, 2));

  // 통계
  const activeProjects = projects.filter(p => (p.commit_count_90d || 0) > 0);
  const inactiveProjects = projects.filter(p => (p.commit_count_90d || 0) === 0 && p.commit_count);

  console.log('\n' + '='.repeat(60));
  console.log('📊 Sync Summary:');
  console.log(`   ✅ Updated: ${updated} projects`);
  console.log(`   ❌ Not Found: ${notFound} projects`);
  console.log(`   ⚠️  Errors: ${errors} projects`);
  console.log(`   📈 Active (90d): ${activeProjects.length} projects`);
  console.log(`   ⏸️  Inactive: ${inactiveProjects.length} projects`);
  console.log(`   📁 Output: ${outputPath}`);
  console.log('='.repeat(60) + '\n');

  return { updated, notFound, errors, outputPath };
}

// CLI Entry Point
const projectsJsonPath = process.argv[2];
if (!projectsJsonPath) {
  console.error('사용법: node sync-updated-at.js <projects.json> [--token TOKEN]');
  console.error('예제: GOGS_TOKEN=abc123 node sync-updated-at.js ~/kim-project-cli/projects.json');
  process.exit(1);
}

(async () => {
  try {
    const result = await syncUpdatedAt(projectsJsonPath);
    console.log(`✨ 동기화 완료! ${result.updated}/${result.updated + result.notFound} 프로젝트 성공`);
  } catch (error) {
    console.error('❌ 오류:', error.message);
    process.exit(1);
  }
