#!/usr/bin/env node

/**
 * P2-1: Health Scorer Algorithm
 *
 * 목적: 각 프로젝트의 건강도를 정량화
 *
 * 채점 공식:
 *   Health Score = (Activity × 0.40) + (Documentation × 0.30) + (Testing × 0.20) + (Community × 0.10)
 *
 * 각 항목별 계산:
 *   - Activity (0-100): 지난 90일 커밋 기반
 *   - Documentation (0-100): README/코드 주석 비율
 *   - Testing (0-100): 테스트 커버리지/테스트 파일 수
 *   - Community (0-100): 스타/포크/이슈/토론 활동
 *
 * 사용법: node health-scorer.js <projects-with-metadata.json>
 */

const fs = require('fs');
const path = require('path');

// 활동성 점수 계산 (0-100)
function calculateActivityScore(commitCount90d, totalCommitCount) {
  if (!commitCount90d && !totalCommitCount) return 0;

  // 기준선: 90일에 12개 커밋 = 월 4개 = 활발
  const activity90d = Math.min(commitCount90d || 0, 36); // 최대 3개월 * 12커밋
  const activityScore = (activity90d / 36) * 100;

  // 전체 커밋도 고려 (오래된 프로젝트는 평가)
  const totalScore = Math.min((totalCommitCount || 0) / 50, 100);

  // 가중치: 최근 활동 70%, 전체 히스토리 30%
  return Math.round(activityScore * 0.7 + totalScore * 0.3);
}

// 문서화 점수 계산 (0-100)
function calculateDocumentationScore(description, name, category) {
  let score = 0;

  // 설명이 있음 (20점)
  if (description && description.length > 10) {
    score += 20;
  }

  // 카테고리별 기본 점수
  if (category === 'core') {
    score += 40; // 핵심 프로젝트는 일반적으로 더 잘 문서화됨
  } else if (category === 'modules') {
    score += 30;
  } else if (category === 'experiments') {
    score += 10;
  } else if (category === 'archived') {
    score += 5;
  }

  // 이름의 명확성 (프로젝트명이 자명함)
  const hasVersionInfo = /v\d+|phase\d+/.test(name);
  if (hasVersionInfo) score += 20;

  // README 존재 여부 (추정)
  const isCoreOrModules = category === 'core' || category === 'modules';
  if (isCoreOrModules) score += 20;

  return Math.min(score, 100);
}

// 테스트 점수 계산 (0-100)
function calculateTestingScore(name, category, description) {
  let score = 0;

  // 카테고리별 기본 점수
  if (category === 'core') {
    score += 50; // 핵심 프로젝트는 테스트가 있을 가능성 높음
  } else if (category === 'modules') {
    score += 40;
  } else if (category === 'experiments') {
    score += 10;
  } else if (category === 'archived') {
    score += 0;
  }

  // 프로젝트명에서 테스트 관련 키워드 찾기
  const testKeywords = ['test', 'spec', 'bench', 'check', 'verify'];
  if (testKeywords.some(kw => name.toLowerCase().includes(kw))) {
    score += 30;
  }

  // 설명에서 테스트 언급 확인
  if (description && description.toLowerCase().includes('test')) {
    score += 20;
  }

  return Math.min(score, 100);
}

// 커뮤니티 점수 계산 (0-100)
function calculateCommunityScore(name, category, status) {
  let score = 0;

  // 활성 상태 (40점)
  if (status === 'active') {
    score += 40;
  } else if (status === 'experimental') {
    score += 20;
  }

  // 메인라인 프로젝트 (v4/v6)는 커뮤니티 더 활발
  if (name.includes('v4-') || name.includes('v6-')) {
    score += 30;
  } else if (name.includes('freelang-')) {
    score += 20;
  }

  // 인기 있는 프로젝트 (이름으로 추정)
  const popularProjects = [
    'freelang-v4-compiler',
    'freelang-blockchain-dpos',
    'freelang-os-kernel',
    'freelang-to-c',
    'fv-lang',
    'sovereign-workspace',
  ];

  if (popularProjects.includes(name)) {
    score += 30;
  }

  return Math.min(score, 100);
}

// 종합 건강도 점수 계산
function calculateHealthScore(project) {
  const activityScore = calculateActivityScore(
    project.commit_count_90d || 0,
    project.commit_count || 0
  );

  const docScore = calculateDocumentationScore(
    project.description,
    project.name,
    project.category
  );

  const testScore = calculateTestingScore(
    project.name,
    project.category,
    project.description
  );

  const communityScore = calculateCommunityScore(
    project.name,
    project.category,
    project.status
  );

  // 가중 평균
  const healthScore = Math.round(
    activityScore * 0.4 +
    docScore * 0.3 +
    testScore * 0.2 +
    communityScore * 0.1
  );

  return {
    healthScore: Math.max(0, Math.min(100, healthScore)),
    activityScore,
    docScore,
    testScore,
    communityScore,
    breakdown: {
      activity: `${activityScore}/100 (최근 90일 커밋: ${project.commit_count_90d || 0})`,
      documentation: `${docScore}/100`,
      testing: `${testScore}/100`,
      community: `${communityScore}/100 (상태: ${project.status})`,
    },
  };
}

// 점수 등급 분류
function getHealthGrade(score) {
  if (score >= 90) return { grade: 'A+', label: 'Excellent', color: '🟢' };
  if (score >= 80) return { grade: 'A', label: 'Good', color: '🟢' };
  if (score >= 70) return { grade: 'B+', label: 'Fair', color: '🟡' };
  if (score >= 60) return { grade: 'B', label: 'Okay', color: '🟡' };
  if (score >= 50) return { grade: 'C', label: 'Poor', color: '🟠' };
  return { grade: 'F', label: 'Critical', color: '🔴' };
}

// 메인 함수
function scoreProjects(projectsJsonPath) {
  if (!fs.existsSync(projectsJsonPath)) {
    console.error(`❌ File not found: ${projectsJsonPath}`);
    process.exit(1);
  }

  const data = JSON.parse(fs.readFileSync(projectsJsonPath, 'utf-8'));
  const projects = Array.isArray(data) ? data : data.projects || [];

  console.log('🔢 Calculating health scores...\n');

  const scoredProjects = projects.map(project => {
    const healthData = calculateHealthScore(project);
    const grade = getHealthGrade(healthData.healthScore);

    return {
      ...project,
      health: {
        score: healthData.healthScore,
        grade: grade.grade,
        label: grade.label,
        color: grade.color,
        breakdown: healthData.breakdown,
        activityScore: healthData.activityScore,
        docScore: healthData.docScore,
        testScore: healthData.testScore,
        communityScore: healthData.communityScore,
      },
    };
  });

  // 점수별 정렬
  const sortedByScore = [...scoredProjects].sort(
    (a, b) => b.health.score - a.health.score
  );

  // 통계 계산
  const scores = scoredProjects.map(p => p.health.score);
  const avgScore = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
  const maxScore = Math.max(...scores);
  const minScore = Math.min(...scores);
  const grades = {
    'A+': 0,
    'A': 0,
    'B+': 0,
    'B': 0,
    'C': 0,
    'F': 0,
  };

  scoredProjects.forEach(p => {
    grades[p.health.grade]++;
  });

  // 상위/하위 10개
  const top10 = sortedByScore.slice(0, 10);
  const bottom10 = sortedByScore.slice(-10).reverse();

  // 콘솔 출력
  console.log(`✅ Top 10 Healthiest Projects:`);
  top10.forEach((p, idx) => {
    console.log(
      `  ${idx + 1}. ${p.health.color} ${p.name.padEnd(35)} → ${p.health.score}/100 (${p.health.grade})`
    );
  });

  console.log(`\n❌ Bottom 10 Least Healthy Projects:`);
  bottom10.forEach((p, idx) => {
    console.log(
      `  ${idx + 1}. ${p.health.color} ${p.name.padEnd(35)} → ${p.health.score}/100 (${p.health.grade})`
    );
  });

  // 파일 저장
  const outputPath = projectsJsonPath.replace('.json', '-scored.json');
  const output = Array.isArray(data) ? scoredProjects : { ...data, projects: scoredProjects };
  fs.writeFileSync(outputPath, JSON.stringify(output, null, 2));

  // 통계 출력
  console.log('\n' + '='.repeat(60));
  console.log('📊 Health Score Summary:');
  console.log(`   📈 Average Score: ${avgScore}/100`);
  console.log(`   🏆 Max Score: ${maxScore}/100`);
  console.log(`   📉 Min Score: ${minScore}/100`);
  console.log(`\n   Grade Distribution:`);
  console.log(`      A+ (90-100): ${grades['A+']} projects`);
  console.log(`      A  (80-89):  ${grades['A']} projects`);
  console.log(`      B+ (70-79):  ${grades['B+']} projects`);
  console.log(`      B  (60-69):  ${grades['B']} projects`);
  console.log(`      C  (50-59):  ${grades['C']} projects`);
  console.log(`      F  (0-49):   ${grades['F']} projects`);
  console.log(`\n   📁 Output: ${outputPath}`);
  console.log('='.repeat(60) + '\n');

  return {
    total: projects.length,
    avgScore,
    grades,
    outputPath,
  };
}

// CLI Entry Point
const projectsJsonPath = process.argv[2];
if (!projectsJsonPath) {
  console.error('사용법: node health-scorer.js <projects-with-metadata.json>');
  console.error('예제: node health-scorer.js ~/kim-project-cli/projects-with-metadata.json');
  process.exit(1);
}

try {
  const result = scoreProjects(projectsJsonPath);
  console.log(
    `✨ 채점 완료! ${result.total}개 프로젝트 평가됨 (평균: ${result.avgScore}/100)`
  );
} catch (error) {
  console.error('❌ 오류:', error.message);
  process.exit(1);
}

