#!/usr/bin/env node

/**
 * P2-2: Maturity Level Analyzer
 *
 * 목적: 각 프로젝트의 성숙도(Maturity Level) 분류
 *
 * 성숙도 레벨:
 *   - Proto (Prototype): 새로운 아이디어/개념 증명 (< 1개월, 작은 규모)
 *   - Alpha (Early Stage): 기본 기능 구현, 불안정 (1-3개월)
 *   - Beta (Mid Stage): 주요 기능 완성, 일부 문제 (3-6개월)
 *   - Production (Release): 안정적, 프로덕션 사용 가능 (6개월+)
 *   - Stable (Mature): 장시간 검증, 최소한의 변화 (1년+)
 *
 * 판단 기준:
 *   1. 나이 (age)
 *   2. 커밋 빈도 (commit_count_90d)
 *   3. 건강도 점수 (health_score)
 *   4. 카테고리 (category)
 *
 * 사용법: node maturity-analyzer.js <projects-scored.json>
 */

const fs = require('fs');
const path = require('path');

// 프로젝트 나이 계산 (개월 단위)
function calculateProjectAge(createdAt, updatedAt) {
  const created = new Date(createdAt || updatedAt || new Date());
  const now = new Date('2026-03-18'); // 현재 기준점

  const monthsDiff = (now.getFullYear() - created.getFullYear()) * 12 +
    (now.getMonth() - created.getMonth());

  return Math.max(0, monthsDiff);
}

// 성숙도 레벨 결정
function determineMaturityLevel(project) {
  const age = calculateProjectAge(project.created_at, project.updated_at);
  const commit90d = project.commit_count_90d || 0;
  const healthScore = project.health?.score || 0;
  const category = project.category || 'core';

  // 아카이브된 프로젝트는 별도
  if (category === 'archived' || project.status === 'archived') {
    return {
      level: 'Archived',
      description: '이전 버전 또는 완료된 프로젝트',
      color: '⚫',
      ageMonths: age,
    };
  }

  // 실험 프로젝트는 Proto/Alpha 범위
  if (category === 'experiments') {
    if (age < 1) {
      return {
        level: 'Proto',
        description: '개념 증명 단계',
        color: '🟣',
        ageMonths: age,
      };
    }
    if (age < 3) {
      return {
        level: 'Alpha',
        description: '초기 단계, 빠른 반복',
        color: '🟠',
        ageMonths: age,
      };
    }
    if (age < 6 || healthScore < 60) {
      return {
        level: 'Beta',
        description: '기본 기능 완성, 개선 중',
        color: '🟡',
        ageMonths: age,
      };
    }
  }

  // Core/Modules 프로젝트 성숙도
  // 1단계: 나이 기반
  let baseLevel = 'Proto';
  if (age >= 12) {
    baseLevel = 'Stable';
  } else if (age >= 6) {
    baseLevel = 'Production';
  } else if (age >= 3) {
    baseLevel = 'Beta';
  } else if (age >= 1) {
    baseLevel = 'Alpha';
  }

  // 2단계: 건강도로 조정
  if (healthScore < 40) {
    // 건강도가 나쁘면 한 단계 낮춤
    const levels = ['Proto', 'Alpha', 'Beta', 'Production', 'Stable'];
    const currentIdx = levels.indexOf(baseLevel);
    baseLevel = currentIdx > 0 ? levels[currentIdx - 1] : 'Proto';
  } else if (healthScore >= 85 && commit90d >= 5) {
    // 건강도가 좋으면 한 단계 높임
    const levels = ['Proto', 'Alpha', 'Beta', 'Production', 'Stable'];
    const currentIdx = levels.indexOf(baseLevel);
    baseLevel = currentIdx < 4 ? levels[currentIdx + 1] : 'Stable';
  }

  // 3단계: 최근 활동 확인 (비활성 프로젝트는 낮춤)
  if (commit90d === 0 && age > 6) {
    const levels = ['Proto', 'Alpha', 'Beta', 'Production', 'Stable'];
    const currentIdx = levels.indexOf(baseLevel);
    baseLevel = currentIdx > 0 ? levels[currentIdx - 1] : 'Proto';
  }

  // 설명 및 색상 할당
  const maturityMap = {
    Proto: {
      description: '개념 증명 단계 - 아이디어 검증',
      color: '🟣',
      riskLevel: 'Very High',
    },
    Alpha: {
      description: '초기 단계 - 빠른 반복 개발',
      color: '🟠',
      riskLevel: 'High',
    },
    Beta: {
      description: '중기 단계 - 주요 기능 완성',
      color: '🟡',
      riskLevel: 'Medium',
    },
    Production: {
      description: '프로덕션 준비 - 안정적 사용 가능',
      color: '🟢',
      riskLevel: 'Low',
    },
    Stable: {
      description: '성숙 단계 - 장시간 검증됨',
      color: '✅',
      riskLevel: 'Very Low',
    },
  };

  const info = maturityMap[baseLevel] || maturityMap.Proto;

  return {
    level: baseLevel,
    ...info,
    ageMonths: age,
    recommendedFor: getRecommendedFor(baseLevel),
  };
}

// 각 성숙도 레벨의 추천 사용 사례
function getRecommendedFor(level) {
  const map = {
    Proto: '실험용, 연구용, 프로토타입 개발',
    Alpha: '얼리 어답터, 피드백 수집용',
    Beta: '베타 테스터, 파일럿 프로젝트',
    Production: '프로덕션 배포, 프로젝트 의존성',
    Stable: '미션 크리티컬 시스템, 장기 유지',
    Archived: '레퍼런스만 참조, 마이그레이션 필요',
  };
  return map[level] || '일반 사용';
}

// 메인 함수
function analyzeMaturity(projectsJsonPath) {
  if (!fs.existsSync(projectsJsonPath)) {
    console.error(`❌ File not found: ${projectsJsonPath}`);
    process.exit(1);
  }

  const data = JSON.parse(fs.readFileSync(projectsJsonPath, 'utf-8'));
  const projects = Array.isArray(data) ? data : data.projects || [];

  console.log('📊 Analyzing project maturity levels...\n');

  const analyzed = projects.map(project => {
    const maturity = determineMaturityLevel(project);

    return {
      ...project,
      maturity: {
        level: maturity.level,
        description: maturity.description,
        color: maturity.color,
        riskLevel: maturity.riskLevel,
        ageMonths: maturity.ageMonths,
        recommendedFor: maturity.recommendedFor,
      },
    };
  });

  // 레벨별 분류
  const levelCounts = {
    Stable: 0,
    Production: 0,
    Beta: 0,
    Alpha: 0,
    Proto: 0,
    Archived: 0,
  };

  const levelProjects = {
    Stable: [],
    Production: [],
    Beta: [],
    Alpha: [],
    Proto: [],
    Archived: [],
  };

  analyzed.forEach(p => {
    const level = p.maturity.level;
    levelCounts[level]++;
    levelProjects[level].push(p);
  });

  // 콘솔 출력
  console.log('✅ Maturity Distribution:');
  console.log(`   ✅ Stable (${levelCounts.Stable}): ${levelProjects.Stable
    .slice(0, 3)
    .map(p => p.name)
    .join(', ')}${levelCounts.Stable > 3 ? '...' : ''}`);
  console.log(`   🟢 Production (${levelCounts.Production}): ${levelProjects.Production
    .slice(0, 3)
    .map(p => p.name)
    .join(', ')}${levelCounts.Production > 3 ? '...' : ''}`);
  console.log(`   🟡 Beta (${levelCounts.Beta}): ${levelProjects.Beta
    .slice(0, 3)
    .map(p => p.name)
    .join(', ')}${levelCounts.Beta > 3 ? '...' : ''}`);
  console.log(`   🟠 Alpha (${levelCounts.Alpha}): ${levelProjects.Alpha
    .slice(0, 3)
    .map(p => p.name)
    .join(', ')}${levelCounts.Alpha > 3 ? '...' : ''}`);
  console.log(`   🟣 Proto (${levelCounts.Proto}): ${levelProjects.Proto
    .slice(0, 3)
    .map(p => p.name)
    .join(', ')}${levelCounts.Proto > 3 ? '...' : ''}`);
  console.log(
    `   ⚫ Archived (${levelCounts.Archived}): 이전 버전 또는 완료 프로젝트`
  );

  // 파일 저장
  const outputPath = projectsJsonPath.replace('.json', '-maturity.json');
  const output = Array.isArray(data) ? analyzed : { ...data, projects: analyzed };
  fs.writeFileSync(outputPath, JSON.stringify(output, null, 2));

  // 통계 출력
  console.log('\n' + '='.repeat(60));
  console.log('📈 Maturity Pyramid:');
  console.log(`   ✅ Stable:      ${levelCounts.Stable.toString().padStart(3)} (${((levelCounts.Stable / projects.length) * 100).toFixed(1)}%)`);
  console.log(`   🟢 Production:  ${levelCounts.Production.toString().padStart(3)} (${((levelCounts.Production / projects.length) * 100).toFixed(1)}%)`);
  console.log(`   🟡 Beta:        ${levelCounts.Beta.toString().padStart(3)} (${((levelCounts.Beta / projects.length) * 100).toFixed(1)}%)`);
  console.log(`   🟠 Alpha:       ${levelCounts.Alpha.toString().padStart(3)} (${((levelCounts.Alpha / projects.length) * 100).toFixed(1)}%)`);
  console.log(`   🟣 Proto:       ${levelCounts.Proto.toString().padStart(3)} (${((levelCounts.Proto / projects.length) * 100).toFixed(1)}%)`);
  console.log(`   ⚫ Archived:     ${levelCounts.Archived.toString().padStart(3)} (${((levelCounts.Archived / projects.length) * 100).toFixed(1)}%)`);
  console.log(`\n   📁 Output: ${outputPath}`);
  console.log('='.repeat(60) + '\n');

  return {
    total: projects.length,
    distribution: levelCounts,
    outputPath,
  };
}

// CLI Entry Point
const projectsJsonPath = process.argv[2];
if (!projectsJsonPath) {
  console.error('사용법: node maturity-analyzer.js <projects-scored.json>');
  console.error('예제: node maturity-analyzer.js ~/kim-project-cli/projects-scored.json');
  process.exit(1);
}

try {
  const result = analyzeMaturity(projectsJsonPath);
  console.log(`✨ 성숙도 분석 완료! ${result.total}개 프로젝트 분류됨`);
} catch (error) {
  console.error('❌ 오류:', error.message);
  process.exit(1);
}

