}

// 주의 필요 판단
function needsAttention(project) {
  const healthScore = project.health?.score || 0;
  const docScore = project.health?.docScore || 0;
  const testScore = project.health?.testScore || 0;
  const commit90d = project.commit_count_90d || 0;
  const category = project.category || '';

  const issues = [];

  // 낮은 건강도
  if (healthScore < 50) {
    issues.push('Health score is low (< 50)');
  }

  // 문서화 부족
  if (docScore < 30) {
    issues.push('Documentation is lacking');
  }

  // 테스트 부족
  if (testScore < 30) {
    issues.push('Testing coverage is low');
  }

  // 비활성이지만 아카이브되지 않음
  if (commit90d === 0 && category !== 'archived' && category !== 'experiments') {
    issues.push('Inactive but not archived');
  }

  // Core인데 점수 낮음
  if (category === 'core' && healthScore < 60) {
    issues.push('Core project with low health');
  }

  return issues.length > 0 ? issues : null;
}

// 프로덕션 승격 판단
function canPromoteToProduction(project) {
  const healthScore = project.health?.score || 0;
  const maturityLevel = project.maturity?.level || '';
  const commit90d = project.commit_count_90d || 0;
  const ageMonths = project.maturity?.ageMonths || 0;

  // 모든 조건 만족
  return (
    healthScore >= 80 && // 좋은 건강도
    (maturityLevel === 'Beta' || maturityLevel === 'Alpha') && // 아직 프로덕션이 아님
    commit90d >= 3 && // 최근 활동 있음
    ageMonths >= 3 // 최소 3개월 운영
  );
}

// 중복/병합 후보 찾기
function findMergeCandidates(projects) {
  const candidates = [];
  const functionMap = {};

  // 기능별 프로젝트 그룹화
  projects.forEach(p => {
    const name = (p.name || '').toLowerCase();
    let primaryFunction = 'other';

    // 주요 기능 카테고리
    if (name.includes('compiler')) primaryFunction = 'compiler';
    else if (name.includes('orm')) primaryFunction = 'orm';
    else if (name.includes('runtime')) primaryFunction = 'runtime';
    else if (name.includes('parser')) primaryFunction = 'parser';
    else if (name.includes('backend')) primaryFunction = 'backend';
    else if (name.includes('blockchain')) primaryFunction = 'blockchain';
    else if (name.includes('database') || name.includes('sqlite')) primaryFunction = 'database';
    else if (name.includes('http') || name.includes('rest')) primaryFunction = 'http';
    else if (name.includes('async')) primaryFunction = 'async';
    else if (name.includes('memory')) primaryFunction = 'memory';

    if (!functionMap[primaryFunction]) {
      functionMap[primaryFunction] = [];
    }
    functionMap[primaryFunction].push(p);
  });

  // 같은 기능 2개 이상 → 병합 검토
  Object.entries(functionMap).forEach(([func, projectList]) => {
    if (projectList.length > 1 && func !== 'other') {
      // 버전별 분리된 것은 제외 (v4, v6 등)
      const versionVariants = projectList.filter(
        p => (p.name || '').match(/v[456]/)
      );

      if (versionVariants.length < projectList.length) {
        // 버전 아닌 실제 중복
        candidates.push({
          function: func,
          projects: projectList.map(p => ({
            name: p.name,
            health: p.health?.score || 0,
            maturity: p.maturity?.level,
          })),
          reason: `${projectList.length} projects provide similar '${func}' functionality`,
        });
      }
    }
  });

  return candidates;
}

// 의존성 업데이트 확인
function checkDependencyUpdates(project, allProjects, dependencies) {
  const issues = [];

  if (!dependencies || !dependencies[project.name]) {
    return issues;
  }

  const projectDeps = dependencies[project.name];
  projectDeps.forEach(depName => {
    const depProject = allProjects.find(p => p.name === depName);

    if (depProject) {
      // 의존성이 비활성이면 경고
      if ((depProject.commit_count_90d || 0) === 0) {
        issues.push(`Depends on inactive project: ${depName}`);
      }

      // 의존성의 건강도가 낮으면 경고
      if ((depProject.health?.score || 0) < 40) {
        issues.push(`Depends on unhealthy project: ${depName} (score: ${depProject.health?.score})`);
      }
    }
  });

  return issues;
}

// 메인 함수
function generateRecommendations(projectsJsonPath, dependenciesPath = null) {
  if (!fs.existsSync(projectsJsonPath)) {
    console.error(`❌ File not found: ${projectsJsonPath}`);
    process.exit(1);
  }

  const data = JSON.parse(fs.readFileSync(projectsJsonPath, 'utf-8'));
  const projects = Array.isArray(data) ? data : data.projects || [];

  // 의존성 로드 (있으면)
  let dependencies = {};
  if (dependenciesPath && fs.existsSync(dependenciesPath)) {
    const depData = JSON.parse(fs.readFileSync(dependenciesPath, 'utf-8'));
    dependencies = depData.dependencies || {};
  }

  console.log('🎯 Generating recommendations...\n');

  // 추천 분류
  const archiveCandidates = projects.filter(p => shouldArchive(p));
  const needsAttentionProjects = projects
    .map(p => ({
      project: p,
      issues: needsAttention(p),
    }))
    .filter(item => item.issues);

  const productionPromotion = projects.filter(p => canPromoteToProduction(p));
  const mergeCandidates = findMergeCandidates(projects);

  // 의존성 이슈 확인
  const dependencyIssues = projects
    .map(p => ({
      project: p,
      issues: checkDependencyUpdates(p, projects, dependencies),
    }))
    .filter(item => item.issues.length > 0);

  // 출력
  console.log(`🗑️  ARCHIVE NOW (${archiveCandidates.length})`);
  archiveCandidates.forEach(p => {
    console.log(`   ❌ ${p.name} (score: ${p.health?.score}/100, 최근 커밋: 없음)`);
  });

  console.log(`\n⚠️  NEEDS ATTENTION (${needsAttentionProjects.length})`);
  needsAttentionProjects.slice(0, 10).forEach(item => {
    console.log(`   ⚡ ${item.project.name}`);
    item.issues.forEach(issue => {
      console.log(`      → ${issue}`);
    });
  });
  if (needsAttentionProjects.length > 10) {
    console.log(`   ... and ${needsAttentionProjects.length - 10} more`);
  }

  console.log(`\n🚀 PROMOTE TO PRODUCTION (${productionPromotion.length})`);
  productionPromotion.forEach(p => {
    console.log(
      `   ✅ ${p.name} (score: ${p.health?.score}/100, maturity: ${p.maturity?.level})`
    );
  });

  console.log(`\n🔀 MERGE CANDIDATES (${mergeCandidates.length} groups)`);
  mergeCandidates.slice(0, 5).forEach(group => {
    console.log(`   ${group.function.toUpperCase()}: ${group.projects.length} projects`);
    group.projects.forEach(proj => {
      console.log(`      → ${proj.name} (health: ${proj.health}/100)`);
    });
  });
  if (mergeCandidates.length > 5) {
    console.log(`   ... and ${mergeCandidates.length - 5} more groups`);
  }

  console.log(`\n🔗 DEPENDENCY ISSUES (${dependencyIssues.length})`);
  dependencyIssues.slice(0, 5).forEach(item => {
    console.log(`   ⚠️  ${item.project.name}`);
    item.issues.forEach(issue => {
      console.log(`      → ${issue}`);
    });
  });
  if (dependencyIssues.length > 5) {
    console.log(`   ... and ${dependencyIssues.length - 5} more`);
  }

  // 파일 저장
  const recommendations = {
    generatedAt: new Date().toISOString(),
    totalProjects: projects.length,
    recommendations: {
      archiveNow: archiveCandidates.map(p => ({
        name: p.name,
        reason: 'Inactive, low health, ready for archival',
        healthScore: p.health?.score,
        commit90d: p.commit_count_90d,
        priority: 'HIGH',
      })),
      needsAttention: needsAttentionProjects.map(item => ({
        name: item.project.name,
        issues: item.issues,
        healthScore: item.project.health?.score,
        priority: 'MEDIUM',
      })),
      promoteToProduction: productionPromotion.map(p => ({
        name: p.name,
        reason: 'High health score, stable, ready for production',
        healthScore: p.health?.score,
        maturity: p.maturity?.level,
        priority: 'HIGH',
      })),
      mergeCandidates: mergeCandidates,
      dependencyIssues: dependencyIssues.map(item => ({
        name: item.project.name,
        issues: item.issues,
        priority: 'MEDIUM',
      })),
    },
    summary: {
      archiveCount: archiveCandidates.length,
      attentionCount: needsAttentionProjects.length,
      promotionCount: productionPromotion.length,
      mergeGroupCount: mergeCandidates.length,
      dependencyIssueCount: dependencyIssues.length,
    },
  };

  const outputPath = projectsJsonPath.replace('.json', '-recommendations.json');
  fs.writeFileSync(outputPath, JSON.stringify(recommendations, null, 2));

  // 통계
  console.log('\n' + '='.repeat(60));
  console.log('📊 Recommendation Summary:');
  console.log(`   🗑️  Archive: ${recommendations.summary.archiveCount}`);
  console.log(`   ⚠️  Attention: ${recommendations.summary.attentionCount}`);
  console.log(`   🚀 Promotion: ${recommendations.summary.promotionCount}`);
  console.log(`   🔀 Merge Groups: ${recommendations.summary.mergeGroupCount}`);
  console.log(`   🔗 Dependency Issues: ${recommendations.summary.dependencyIssueCount}`);
  console.log(`   📁 Output: ${outputPath}`);
  console.log('='.repeat(60) + '\n');

  return recommendations.summary;
}

// CLI Entry Point
const projectsJsonPath = process.argv[2];
const dependenciesPath = process.argv[3];

if (!projectsJsonPath) {
  console.error('사용법: node recommendation-engine.js <projects-maturity.json> [dependencies.json]');
  console.error(
    '예제: node recommendation-engine.js ~/kim-project-cli/projects-maturity.json'
  );
  process.exit(1);
}

try {
  const summary = generateRecommendations(projectsJsonPath, dependenciesPath);
  console.log(`✨ 권고 생성 완료!`);
} catch (error) {
  console.error('❌ 오류:', error.message);
  process.exit(1);
}

