#!/usr/bin/env node

/**
 * Alternative P1-3: Sync via Git Clone
 * GOGS API 인증 문제를 우회하고 git 명령어로 커밋 정보 수집
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// 알려진 GOGS 리포지토리 (수동)
const GOGS_REPOS = {
  'freelang-v4-compiler': 'kim/freelang-v4-compiler',
  'freelang-blockchain-dpos': 'kim/freelang-blockchain-dpos',
  'freelang-os-kernel': 'kim/freelang-os-kernel',
  'freelang-to-c': 'kim/freelang-to-c',
  'fv-lang': 'kim/fv-lang',
  'sovereign-workspace': 'kim/sovereign-workspace',
  'personal-code-os': 'kim/personal-code-os',
  'freewire': 'kim/freewire',
  'kim-project-cli': 'kim/kim-project-cli',
  'freelang-project-excellence': 'kim/freelang-project_excellence',
};

const GOGS_URL = 'https://gogs.dclub.kr';

function getCommitInfo(projectName, gogsPath) {
  try {
    const tmpDir = `/tmp/gogs-clone-${Date.now()}`;
    const repoUrl = `${GOGS_URL}/${gogsPath}.git`;

    console.log(`  🔄 ${projectName}...`);

    // Shallow clone (빠름)
    execSync(`git clone --depth=1 ${repoUrl} ${tmpDir} 2>/dev/null`, {
      timeout: 10000,
    });

    // 커밋 정보 수집
    const allCommits = execSync(`cd ${tmpDir} && git log --format=%ai`, {
      encoding: 'utf-8',
    }).split('\n').filter(l => l);

    const now = new Date();
    const ninetyDaysAgo = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
    const recent = allCommits.filter(line => {
      const date = new Date(line.split(' ')[0]);
      return date >= ninetyDaysAgo;
    }).length;

    const lastCommitDate = allCommits[0] ? allCommits[0].split(' ')[0] : null;
    const lastCommitAuthor = execSync(
      `cd ${tmpDir} && git log -1 --format=%an`,
      { encoding: 'utf-8' }
    ).trim();

    // 정리
    execSync(`rm -rf ${tmpDir}`);

    return {
      success: true,
      commit_count: allCommits.length,
      commit_count_90d: recent,
      updated_at: lastCommitDate,
      last_commit_author: lastCommitAuthor,
    };
  } catch (error) {
    return {
      success: false,
      error: error.message,
    };
  }
}

function syncViaGit(projectsJsonPath) {
  if (!fs.existsSync(projectsJsonPath)) {
    console.error(`❌ File not found: ${projectsJsonPath}`);
    process.exit(1);
  }

  const data = JSON.parse(fs.readFileSync(projectsJsonPath, 'utf-8'));
  const projects = Array.isArray(data) ? data : data.projects || [];

  console.log(
    `🔍 Syncing ${Object.keys(GOGS_REPOS).length} known GOGS repositories...\n`
  );

  let synced = 0;
  let failed = 0;

  const enhanced = projects.map(project => {
    const projectName = project.name || '';

    if (GOGS_REPOS[projectName]) {
      const result = getCommitInfo(projectName, GOGS_REPOS[projectName]);

      if (result.success) {
        project.commit_count = result.commit_count;
        project.commit_count_90d = result.commit_count_90d;
        project.updated_at = result.updated_at;
        project.last_commit_author = result.last_commit_author;
        synced++;
        console.log(`     ✅ ${result.commit_count} commits, ${result.commit_count_90d} in 90d`);
      } else {
        failed++;
        console.log(`     ❌ Clone failed: ${result.error}`);
      }
    }

    return project;
  });

  // 저장
  const outputPath = projectsJsonPath.replace('.json', '-git-synced.json');
  const output = Array.isArray(data) ? enhanced : { ...data, projects: enhanced };
  fs.writeFileSync(outputPath, JSON.stringify(output, null, 2));

  console.log('\n' + '='.repeat(60));
  console.log('📊 Git Sync Summary:');
  console.log(`   ✅ Synced: ${synced}`);
  console.log(`   ❌ Failed: ${failed}`);
  console.log(`   📁 Output: ${outputPath}`);
  console.log('='.repeat(60) + '\n');
}

const projectsJsonPath = process.argv[2];
if (!projectsJsonPath) {
  console.error('사용법: node sync-via-git.js <projects.json>');
  process.exit(1);
}

syncViaGit(projectsJsonPath);
EOF

